document.addEventListener("contextmenu",e=>e.preventDefault()),document.addEventListener("keydown",e=>{if(123===e.keyCode||e.ctrlKey&&e.shiftKey&&(73===e.keyCode||74===e.keyCode||67===e.keyCode)||e.ctrlKey&&85===e.keyCode)return e.preventDefault(),!1}),setInterval(function(){const e=performance.now();performance.now()-e>50&&(document.body.innerHTML="<h2 style='color:red;text-align:center;margin-top:50px;'>CẢNH BÁO: Không được phép xem mã nguồn!</h2>",window.location.reload())},500);